static int *parentNode;
static ll *nodeWeight, *nodeSum;
static int nodeCount;

static int findRoot(int x) {
    int r = x;
    while (dsu[r] != r) r = dsu[r];
    while (dsu[x] != x) {
        int next = dsu[x];
        dsu[x] = r;
        x = next;
    }
    return r;
}

static void unite(int a, int b, ll weight) {
    int ra = findRoot(a);
    int rb = findRoot(b);
    if (ra == rb) return;

    if (dsuSize[ra] < dsuSize[rb]) {
        int tmp = ra;
        ra = rb;
        rb = tmp;
    }

    int left = treeRoot[ra];
    int right = treeRoot[rb];
    int node = nodeCount++;

    nodeWeight[node] = weight;
    nodeSum[node] = nodeSum[left] + nodeSum[right];
    parentNode[node] = -1;
    parentNode[left] = node;
    parentNode[right] = node;

    dsu[rb] = ra;
    dsuSize[ra] += dsuSize[rb];
    treeRoot[ra] = node;
}

